from pathlib import Path
import hashlib,json
import numpy as np,pandas as pd
R=Path.cwd();O=R/'outputs/validation_error_report';path=R/'outputs/strategy3_v1/graph_oof.csv';q=pd.read_csv(path)
labels=pd.read_csv(R/'data/training/train/labels.csv').set_index('TRANSACTION_HASH');assert q.TRANSACTION_HASH.is_unique;assert set(q.TRANSACTION_HASH)==set(labels.index)
for col in labels.columns:assert q.set_index('TRANSACTION_HASH')[col].fillna('').equals(labels.loc[q.TRANSACTION_HASH,col].fillna(''))
order=np.lexsort((q.TRANSACTION_HASH.to_numpy(),-q.score.to_numpy()));rank=np.empty(len(q),int);rank[order]=np.arange(1,len(q)+1);q['validation_rank']=rank;k=int(np.ceil(len(q)*.01));q['reviewed']=rank<=k;q['error']=np.where(q.is_suspicious.eq(0)&q.reviewed,'FP',np.where(q.is_suspicious.eq(1)&~q.reviewed,'FN',np.where(q.is_suspicious.eq(1),'TP','TN')))
q['category']=np.where(q.is_suspicious.eq(0),'legitimate',np.where(q.difficulty.eq('hard'),np.where(q.family.eq('ambiguous'),'ambiguous','observable-hard'),q.difficulty))
conf=q.error.value_counts().to_dict();assert conf=={'TN':38805,'FN':924,'TP':326,'FP':76},conf
fp=[];fn=[];combined=[];bands=[]
for family,g in q.groupby('family'):
 legit=g[g.is_suspicious.eq(0)];positives=g[g.is_suspicious.eq(1)];fpos=g[g.error.eq('FP')];fneg=g[g.error.eq('FN')];tp=int(g.error.eq('TP').sum())
 combined.append({'type':family,'legitimate_total':len(legit),'false_positives':len(fpos),'true_negatives':int(g.error.eq('TN').sum()),'suspicious_total':len(positives),'caught':tp,'false_negatives':len(fneg)})
 if len(fpos):fp.append({'type':family,'legitimate_total':len(legit),'false_positives':len(fpos),'false_positive_rate_pct':100*len(fpos)/len(legit),'share_of_76_false_positives_pct':100*len(fpos)/76,'highest_global_rank':int(fpos.validation_rank.min()),'median_global_rank':float(fpos.validation_rank.median()),'highest_score':float(fpos.score.max()),'median_score':float(fpos.score.median())})
 if len(positives):
  row={'type':family,'suspicious_total':len(positives),'caught_top402':tp,'false_negatives':len(fneg),'miss_rate_pct':100*len(fneg)/len(positives),'median_missed_global_rank':float(fneg.validation_rank.median()) if len(fneg) else np.nan,'lowest_missed_global_rank':int(fneg.validation_rank.max()) if len(fneg) else None,'median_missed_score':float(fneg.score.median()) if len(fneg) else None}
  for c in ['easy','medium','observable-hard','ambiguous']:row[c+'_missed']=int((fneg.category==c).sum())
  fn.append(row)
  bands.append({'type':family,**{name:int(fneg.validation_rank.between(lo,hi).sum()) for name,lo,hi in [('ranks_403_1000',403,1000),('ranks_1001_5000',1001,5000),('ranks_5001_10000',5001,10000),('ranks_10001_20000',10001,20000),('ranks_over_20000',20001,len(q))]}})
fp=pd.DataFrame(fp).sort_values(['false_positives','type'],ascending=[False,True]);fn=pd.DataFrame(fn).sort_values(['false_negatives','type'],ascending=[False,True]);pd.DataFrame(combined).to_csv(O/'all_types_summary.csv',index=False);fp.to_csv(O/'false_positives_by_type.csv',index=False);fn.to_csv(O/'false_negatives_by_type.csv',index=False);pd.DataFrame(bands).to_csv(O/'missed_rank_bands_by_type.csv',index=False)
cols=['validation_rank','TRANSACTION_HASH','fold','family','category','is_suspicious','score','error']
q[q.error.eq('FP')].sort_values('validation_rank')[cols].to_csv(O/'all_76_false_positives.csv',index=False)
q[q.error.eq('FN')].sort_values('validation_rank')[cols].to_csv(O/'all_924_false_negatives.csv',index=False)
q[q.error.eq('FN')].sort_values('validation_rank',ascending=False)[cols].to_csv(O/'false_negatives_lowest_first.csv',index=False)
folds=[]
for f,g in q.groupby('fold'):
 counts=g.error.value_counts();folds.append({'fold':int(f),'transactions':len(g),'included_in_pooled_top402':int(g.reviewed.sum()),**{c:int(counts.get(c,0)) for c in ['TP','FP','FN','TN']}})
pd.DataFrame(folds).to_csv(O/'fold_error_counts.csv',index=False)
def table(d):
 def fmt(v):return f'{v:.2f}' if isinstance(v,(float,np.floating)) else str(v)
 return '| '+' | '.join(d.columns)+' |\n| '+' | '.join(['---']*len(d.columns))+' |\n'+'\n'.join('| '+' | '.join(fmt(x) for x in row)+' |' for row in d.to_numpy())
readfp=fp[['type','false_positives','legitimate_total','false_positive_rate_pct','median_global_rank']].rename(columns={'type':'Type','false_positives':'FP: legitimate ranked top 402','legitimate_total':'All legitimate of type','false_positive_rate_pct':'False alarm rate %','median_global_rank':'Median FP rank'})
readfn=fn[['type','suspicious_total','caught_top402','false_negatives','miss_rate_pct','median_missed_global_rank']].rename(columns={'type':'Type','suspicious_total':'All suspicious','caught_top402':'Caught','false_negatives':'FN: missed','miss_rate_pct':'Miss rate %','median_missed_global_rank':'Median missed rank'})
cat=[]
for c in ['easy','medium','observable-hard','ambiguous']:
 z=q[q.category.eq(c)];n=int(z.error.eq('FN').sum());cat.append({'Category':c,'Suspicious':len(z),'Caught':int(z.error.eq('TP').sum()),'Missed':n,'Miss rate %':100*n/len(z)})
ct=pd.DataFrame(cat);ct.to_csv(O/'difficulty_summary.csv',index=False)
text=['# V1 validation false positives and false negatives','', 'This is the frozen V1 pooled out-of-fold validation result, not the official test Run 1. Every transaction was scored by a model that did not train on its label. The original validation still shares unlabelled wallets/graph context across folds, as permitted for the offline task.','',f'Rank 1 is most suspicious. Review budget: top {k} of {len(q):,} transactions (1%, rounded up), ordered by descending score then ascending transaction hash for ties. A false positive is legitimate but reviewed; a false negative is suspicious but outside the review budget. This is not a fixed 0.5 classification threshold. The last included score is {q.loc[q.validation_rank.eq(k),"score"].iloc[0]:.10f}.','', '**Overall:** 326 suspicious caught; 76 legitimate reviewed; 924 suspicious missed; 38,805 legitimate correctly left outside the budget. Precision 81.09%; recall 26.08%. All 1,000 operational errors are included; FN is not limited to the previously examined bottom-125 subset.','', '## False positives - legitimate payments ranked too high','',table(readfp),'', 'These 10 rows cover all 76 false positives. Fan-out, ambiguous and background have no false positives at this cutoff. Family labels describe the supplied synthetic transaction types; they do not imply that every matching observable pattern is suspicious.','', '## False negatives - suspicious payments left below rank 402','',table(readfn),'',f'Total: {int(fn.suspicious_total.sum())} suspicious, {int(fn.caught_top402.sum())} caught, {int(fn.false_negatives.sum())} missed. Median missed rank is calculated among missed suspicious payments of that type; larger numbers mean deeper misses. Aggregate/distributed relay are the 200 observable-hard cases; ambiguous is separate. All legitimate, caught and missed type totals, including zero-error background, are in all_types_summary.csv.','', '## Missed cases by difficulty','',table(ct),'', '## Severity within missed cases','',table(pd.DataFrame(bands).sort_values('ranks_over_20000',ascending=False)),'', '## What repeats','', '- High-ranked false positives recur across lawful chains (16), bipartite flows (14), aggregate relays (12), and multi-stage payments (9). The prior held-out attribution audit found one-off pairs and short bursts/rapid-flow compatibility boosting many such legitimate payments. This is a repeated model behaviour, not an explanation inferred from a single transaction.','- The largest counts of missed positives are shown above. The rank and score columns distinguish payments just below the cutoff from payments buried deep in the list. The supplied ambiguous cases are deliberately indistinguishable by their labels from ordinary activity; the observable-hard cases should not be assumed unlearnable.','- These are counts per transaction, not counts of independent wallets or laundering scenarios. Type/difficulty annotations are used only to describe errors, never as model inputs.','', '## Complete row-level files','', '- all_76_false_positives.csv: every false alarm, highest ranked first.','- all_924_false_negatives.csv: every missed positive, nearest the review cutoff first.','- false_negatives_lowest_first.csv: the same 924 misses, worst ranked first.','- false_positives_by_type.csv and false_negatives_by_type.csv: full numeric type summaries.','- missed_rank_bands_by_type.csv: how deep the misses are.','- fold_error_counts.csv: fold origin of pooled errors; these counts use the common top-402 budget, not a separate top-134 budget per fold.','', 'All numbers are regenerated from outputs/strategy3_v1/graph_oof.csv and checked against the original training labels. No model fitting, new predictions, upload or submission occurred. V1 artifacts remain unchanged.']
(O/'Validation_FP_FN_Report.md').write_text('\n'.join(text)+'\n')
# Preservation proof and count reconciliation.
protected=json.loads((R/'outputs/v2_experiments/v1_protection_manifest.json').read_text());assert all(hashlib.sha256((R/x['path']).read_bytes()).hexdigest()==x['sha256'] for x in protected);assert fp.false_positives.sum()==76;assert fn.false_negatives.sum()==924;assert fn.caught_top402.sum()==326;assert sum(sum(x[k] for k in x if k.startswith('ranks_')) for x in bands)==924
(O/'verification.json').write_text(json.dumps({'source_oof_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'label_alignment':'PASS','counts':conf,'review_budget':k,'transactions':len(q),'protected_v1_files_unchanged':len(protected),'false_negative_definition':'all suspicious outside pooled top402; not only bottom125','submitted':False},indent=2)+'\n')
print(table(readfp));print('\n'+table(readfn));print('\n'+table(ct))
